async function review(r,d,status,key,subject){const q=await r.bound(d);assert.equal(q.status,status);assert.deepEqual(q.errors,[]);assert.deepEqual(q[key],subject);assert.equal(q.newSearches??q.newGameplaySearches,0);return q;}
async function qualification(r,d){const q=await r.bound(d);assert.equal(q.status,QUALIFICATION_STATUS);assert.deepEqual(q.errors,[]);assert.equal(q.searchAlgorithmChanged,false);assert.equal(q.failedOriginalRetryAllowed,false);for(const k of ['newRealConstructions','newSearches','publicClaimsStarted'])assert.equal(q[k],0);for(const f of [SELF,ICE_ENTRY,'tools/daily-challenge/formal-v4/plan-history-adapter-v5.mjs','tools/daily-challenge/formal-v4/supplemental-comparison-evidence.mjs'])assert(q.toolBindings[f]);await r.map(q.toolBindings);
 const module=await r.bound(MODULE_REVIEW);assert.equal(module.status,'INDEPENDENT_PARKING_ICE_REGION_TASK_PASS');assert.deepEqual(module.errors,[]);return q;}
