async function historyListing(scope){const listing={};for(const root of scope.roots){const files=[];const visit=async dir=>{for(const e of await fs.readdir(dir,{withFileTypes:true})){assert(!e.isSymbolicLink(),'History listing must not follow a nested alias');const f=path.join(dir,e.name);if(e.isDirectory())await visit(f);else if(e.isFile())files.push(f);}};if(await exists(root.physicalPath))await visit(root.physicalPath);listing[root.id]=files;}return listing;}
// An intermediate sealed-facts view is not a live filesystem observation.
// Every phase separately checks the complete no-follow live membership via members().
export function declaredHistoryMembership(h,delta){const scope=h.bundle.scope,listing=Object.fromEntries(scope.roots.map(x=>[x.id,[]])),seen=new Set(),compiler=compileCanonicalHistoryPath(scope);
 for(const f of [...h.bundle.files,...delta.files])if(f.rootId!==null){assert(Object.hasOwn(listing,f.rootId));const c=compiler.canonical(f.path);assert(!seen.has(c),'Duplicate declared history member');seen.add(c);listing[f.rootId].push(f.path);}return listing;}
async function history(r,p){assert.equal(p.historyScope.roots.length,7);assert.deepEqual((await Promise.all(p.historyScope.roots.map(x=>realPathWithSuffix(x.physicalPath)))).sort(),(await Promise.all(HISTORY_LEDGER_ROOTS.map(realPathWithSuffix))).sort());let h=await consumePlanHistory({checkpoint:p.history,review:p.historyReview,expectedScope:p.historyScope,readBytes:r.bytes});
 assert(Array.isArray(p.historyDeltas??[]));for(const x of p.historyDeltas??[]){descriptor(x.descriptor);descriptor(x.declaredOwner.definition);const delta=await r.bound(x.descriptor);h=await mergePlanHistoryDelta(h,{...x,listing:declaredHistoryMembership(h,delta),readBytes:r.bytes});}return h;}
async function members(h,allowed=[]){const scope=h.bundle.scope,additions=[...new Set(allowed)].map(file=>{const canonical=canonicalHistoryPath(path.resolve(file),scope),root=scope.roots.find(x=>canonical.startsWith(canonicalHistoryPath(x.physicalPath,scope)+'/'));assert(root,'Addition outside seven history roots');return{path:path.resolve(file),rootId:root.id};});return assertPlanHistoryMembers(h,await historyListing(scope),additions);}
async function directRole(r,h,receipt,role){const q=await r.bound(receipt),a=q.attempt??q.proof?.attempt;assert(a?.id,'No invented historical attempt');
 const matches=Object.values(h.terminalByAttempt).filter(x=>levelSha256(x.request.value)===levelSha256(a));assert.equal(matches.length,1,'Unambiguous real historical namespace required');const x=await readDirectHistoryRole(h,{namespace:matches[0].namespace,attemptId:a.id,receipt,role,readBytes:r.bytes});await r.map(x.fileBindings);return x;}
async function comparison(r,h,p){const view=await readSupplementalComparisonEvidence(h,{provenance:p.comparison.provenance,review:p.comparison.review,readBytes:r.bytes,qualificationOnly:false,role:'comparison-only'});if(p.comparisonEvidence)assert.deepEqual(view.comparisonEvidence,p.comparisonEvidence);return view;}

async function parents(r,h,specs){const rows=[];for(const x of specs){const readiness=await directRole(r,h,x.receipt,'failed-parent'),q=readiness.receipt,a=readiness.request;
 assert.equal(q.accepted,false);assert.equal(q.sourceLevelId??q.level.id,x.sourceLevelId);assert.equal(q.levelSha256,levelSha256(q.level));assert.equal(a.id,x.attemptId);assert.deepEqual(await r.bound(x.request),a);assert.deepEqual(await r.bound(x.result),readiness.result);
 const canonical=compileCanonicalHistoryPath(h.bundle.scope).canonical;for(const k of ['originalIdentitySeal','retryIdentitySeal']){const seal=await r.bound(x[k]);assert.equal(seal.attemptId,a.id);assert(readiness.blocked.some(b=>b.descriptor.sha256===x[k].sha256&&canonical(b.descriptor.path)===canonical(x[k].path)));}rows.push({...x,branchId:'parking-ice-source29',id:a.id,fingerprints:designFingerprints(q.level)});}return rows;}
async function opened(d){const r=reader(),p=await r.bound(d);assertParkingIcePlan(p);await r.map(p.bindings);const context=await r.bound(p.contextDescriptor);
 for(const k of ['history','historyReview','historyScope','proposal','proposalReview','qualification','comparison'])assert.deepEqual(context[k],p[k]);assert.deepEqual(context.historyDeltas??[],p.historyDeltas);
 const rt=await loadV4CatalogRuntime();assert.deepEqual(prefixExecutionEnvironment(rt),p.executionEnvironment);const h=await history(r,p),view=await comparison(r,h,p);assert.equal(h.headSha256,p.historyHeadSha256);
 assert.deepEqual(await parents(r,h,p.proposalData.failedParents),p.failedParents);for(const b of p.blueprints){assert.deepEqual(b.canonicalReference,{path:await fs.realpath(b.reference.path),sha256:b.reference.sha256});const x=await currentMainlineSourceBinding(rt,p.executionEnvironment,b.sourceLevelId);await r.map(x.bindings);assert.equal(x.sourceLevelSha256,b.sourceLevelSha256);}return{r,p,rt,h,pool:view.comparisonView.nearPools};}
export async function prepareParkingIceBatch(context){
 const r=reader(),rt=await loadV4CatalogRuntime(),environment=prefixExecutionEnvironment(rt);await bindTools(r,rt);await r.map(environment.bindings);const proposal=await r.bound(context.proposal);assertParkingIceProposal(proposal);
 await review(r,context.proposalReview,PROPOSAL_REVIEW_STATUS,'proposal',context.proposal);await qualification(r,context.qualification);const raw=await r.bound(context.contextDescriptor);
 for(const k of ['history','historyReview','historyScope','proposal','proposalReview','qualification','comparison'])assert.deepEqual(raw[k],context[k]);assert.deepEqual(raw.historyDeltas??[],context.historyDeltas??[]);
 const h=await history(r,context),view=await comparison(r,h,context);await members(h);assert(!h.closedExperimentIds.includes(proposal.experimentId),'Closed experiment cannot be restarted');
 const evidence=await readSeparated161SelectionEvidence(proposal.selectionReview,{bindings:r.bindings});assert.deepEqual(evidence.selection,proposal.selection);const selection=await r.bound(proposal.selection);assert.deepEqual(selection.files,h.nearPools.selected.map(x=>x.descriptor.path));const selected=[];
 for(const x of h.nearPools.selected){const q=await r.bound(x.descriptor);assert.deepEqual(q.level,x.level);selected.push(q);}assert.deepEqual(auditV4Diversity(selected,rt.slots).reasons,[]);
 const failedParents=await parents(r,h,proposal.failedParents),blueprints=[];for(const recipe of proposal.recipes){const b=await validateReference(rt,r,h,proposal.references[0],recipe);b.canonicalReference={path:await fs.realpath(b.reference.path),sha256:b.reference.sha256};const x=await currentMainlineSourceBinding(rt,environment,b.sourceLevelId);await r.map(x.bindings);assert.equal(x.sourceLevelSha256,b.sourceLevelSha256);blueprints.push(b);}
 const p={version:VERSION,experimentId:proposal.experimentId,contextDescriptor:context.contextDescriptor,proposal:context.proposal,proposalData:proposal,proposalReview:context.proposalReview,qualification:context.qualification,moduleQualification:MODULE_REVIEW,
  history:context.history,historyReview:context.historyReview,historyScope:context.historyScope,historyDeltas:context.historyDeltas??[],historyHeadSha256:h.headSha256,comparison:context.comparison,comparisonEvidence:view.comparisonEvidence,selection:proposal.selection,selectionReview:proposal.selectionReview,selectedCount:selected.length,
  blueprints,failedParents,executionEnvironment:environment,proofToolchainSha256:rt.toolchainSha256,futureJointBudget:UPPER_BUDGET,strategy:STRATEGY,historicalBytesRevalidated:false,historyValidation:'reviewed-checkpoint-deltas-comparison-and-direct-active-roles',excludedHistoricalUIBindings:evidence.excludedUIBindings,bindings:r.bindings,...failFlags};
 assertParkingIcePlan(p);await members(h);await r.finish();return p;
}

export function parkingIceConstructionFiles(d,p){return[`${d.sha256}.claim.json`,`${d.sha256}.result.json`,`experiment-${levelSha256({experimentId:p.experimentId})}.execution.json`,`proposal-${p.proposal.sha256}.execution.json`].map(f=>path.join(LATE_PREFIX_CONSTRUCTION_LEDGER,f));}
export function assertParkingIceLedgerPaths(ledgerDirectory,actualPhysical,expectedPhysical){assert.equal(path.resolve(ledgerDirectory),path.resolve(LATE_PREFIX_CONSTRUCTION_LEDGER),'Original claim requires the shared lexical path');assert.equal(actualPhysical,expectedPhysical,'History and claim must share the same physical namespace');return true;}
