   const file=`${out}/construction-${String(attempts.length).padStart(4,'0')}.json`;await write(file,{...built,plan:d,recipeId:b.recipeId,executionPolicyObservation:observation});a.constructionEvidence=await fileDescriptor(file);attempts.push(a);assertParkingIceStock(built,b,seed);const previous=recordStock(state,b,built);
